19	export class ContactWizard {
20	  private static readonly _CLASS = "ContactWizard";
21	  private readonly _root: HTMLElement;
22	  private readonly _form: HTMLFormElement | null;
23	  private readonly _viewport: HTMLElement | null;
24	  private readonly _steps: HTMLElement[];
25	  private readonly _overviewList: HTMLOListElement | null;
26	  private readonly _prevButtons: HTMLButtonElement[];
27	  private readonly _primaryActionButtons: HTMLButtonElement[];
28	  private readonly _projectOtherToggle: HTMLInputElement | null;
29	  private readonly _projectOtherPanel: HTMLElement | null;
30	  private readonly _projectOtherInput: HTMLInputElement | null;
31	  private readonly _sidebarSyncDebounce: Debounce;
32	  private readonly _chipLeaveTimers = new WeakMap<HTMLElement, number>();
33	  private readonly _chipMoveAnimations = new WeakMap<HTMLElement, Animation>();
34	  private readonly _previousActionHideTimers = new WeakMap<HTMLElement, number>();
35	  private readonly _activeTimers = new Set<number>();
36	  private readonly _activeAnimations = new Set<Animation>();
37	  private readonly _onClickBound: (event: Event) => void;
38	  private readonly _onChangeBound: () => void;
39	  private readonly _onInputBound: (event: Event) => void;
40	  private readonly _onSubmitBound: (event: Event) => void;
41	  private readonly _onFormKeydownBound: (event: KeyboardEvent) => void;
42	  private _mounted = false;
43	  private _disposed = false;
44	  private _navItems: HTMLElement[] = [];
45	  private _stepValues: HTMLElement[] = [];
46	  private _current = 0;
47	  private _busy = false;
48	  private _submitting = false;
49	  private _lastOverviewScrollIndex = -1;
50	
51	  private static _instances = new Set<ContactWizard>();
52	
53	  static init(options: ContactWizardInitOptions = {}): void {
54	    const scope = options.root ?? document;
55	    scope
56	      .querySelectorAll<HTMLElement>(CONTACT_WIZARD.selector)
57	      .forEach((element) => {
58	        const instance = new ContactWizard(element);
59	        ContactWizard._instances.add(instance);
60	        instance.mount();
61	      });
62	  }
63	
64	  static dispose(): void {
65	    ContactWizard._instances.forEach((instance) => instance.dispose());
66	    ContactWizard._instances.clear();
67	  }
68	
69	  constructor(root: HTMLElement) {
70	    this._root = root;
71	    this._form = root.closest("form");
72	    this._viewport = root.querySelector<HTMLElement>("[data-wizard-viewport]");
73	    this._steps = Array.from(
74	      root.querySelectorAll<HTMLElement>("[data-wizard-step]"),
75	    );
76	    this._overviewList = root.querySelector<HTMLOListElement>(
77	      "[data-wizard-overview-list]",
78	    );
79	    this._prevButtons = Array.from(
80	      root.querySelectorAll<HTMLButtonElement>("[data-wizard-prev]"),
81	    );
82	    this._primaryActionButtons = Array.from(
83	      root.querySelectorAll<HTMLButtonElement>("[data-wizard-primary-action]"),
84	    );
85	    this._projectOtherToggle = root.querySelector<HTMLInputElement>(
86	      "[data-project-other-toggle]",
87	    );
88	    this._projectOtherPanel = root.querySelector<HTMLElement>(
89	      "[data-project-other-panel]",
90	    );
91	    this._projectOtherInput = root.querySelector<HTMLInputElement>(
92	      "[data-project-other-input]",
93	    );
94	    this._sidebarSyncDebounce = new Debounce(
95	      CONTACT_WIZARD.summaryInputDebounceMs,
96	    );
97	    this._onClickBound = (event) => this._onClick(event as MouseEvent);
98	    this._onChangeBound = () => {
99	      this._sidebarSyncDebounce.offCancel();
100	      this._syncProjectOtherField();
101	      this._syncSidebar();
102	    };
103	    this._onInputBound = (event) => {
104	      this._syncProjectOtherField();
105	      if (this._shouldDebounceSidebarSync(event.target)) {
106	        this._sidebarSyncDebounce.runDebounce(() => this._syncSidebar());
107	        return;
108	      }
109	      this._syncSidebar();
110	    };
111	    this._onSubmitBound = (event) => this._onSubmit(event as SubmitEvent);
112	    this._onFormKeydownBound = (event) => this._onFormKeydown(event);
113	  }
114	
115	  dispose(): void {
116	    if (this._disposed) return;
117	    this._disposed = true;
118	    if (this._mounted) {
119	      this._root.removeEventListener("click", this._onClickBound);
120	      this._root.removeEventListener("change", this._onChangeBound);
121	      this._root.removeEventListener("input", this._onInputBound);
122	      this._form?.removeEventListener("submit", this._onSubmitBound);
123	      this._form?.removeEventListener("keydown", this._onFormKeydownBound, true);
124	      this._mounted = false;
125	    }
126	    this._sidebarSyncDebounce.offCancel();
127	    this._activeTimers.forEach((id) => window.clearTimeout(id));
128	    this._activeTimers.clear();
129	    this._activeAnimations.forEach((animation) => animation.cancel());
130	    this._activeAnimations.clear();
131	    ContactWizard._instances.delete(this);
132	  }
133	
134	  private _trackedTimeout(callback: () => void, delay: number): number {
135	    const id = window.setTimeout(() => {
136	      this._activeTimers.delete(id);
137	      if (this._disposed) return;
138	      callback();
139	    }, delay);
140	    this._activeTimers.add(id);
141	    return id;
142	  }
143	
144	  private _trackAnimation(animation: Animation): Animation {
145	    this._activeAnimations.add(animation);
146	    const cleanup = () => this._activeAnimations.delete(animation);
147	    animation.addEventListener("finish", cleanup, { once: true });
148	    animation.addEventListener("cancel", cleanup, { once: true });
149	    return animation;
150	  }
151	
152	  private mount(): void {
153	    if (!this._viewport || this._steps.length === 0) return;
154	
155	    const totalElement =
156	      this._root.querySelector<HTMLElement>("[data-wizard-total]");
157	    if (totalElement) {
158	      totalElement.textContent = String(this._steps.length).padStart(2, "0");
159	    }
160	
161	    this._renderOverview();
162	    this._root.addEventListener("click", this._onClickBound);
163	    this._root.addEventListener("change", this._onChangeBound);
164	    this._root.addEventListener("input", this._onInputBound);
165	    this._form?.addEventListener("submit", this._onSubmitBound);
166	    this._form?.addEventListener("keydown", this._onFormKeydownBound, true);
167	    this._mounted = true;
168	
169	    this._steps.forEach((step, index) => {
170	      step.classList.toggle("is-active", index === 0);
171	      step.classList.remove("is-prev");
172	    });
173	
174	    this._syncIndicator(true);
175	    this._syncProjectOtherField();
176	    this._syncSidebar();
177	  }
178	
179	  private _renderOverview(): void {
180	    if (!this._overviewList) return;
181	
182	    const fragment = document.createDocumentFragment();
183	    this._steps.forEach((step, index) => {
184	      const item = document.createElement("li");
185	      item.className = "no-wizard-overview__item";
