227	  private _onClick(event: Event): void {
228	    if (this._submitting) return;
229	    const target = event.target;
230	    if (!(target instanceof HTMLElement)) return;
231	
232	    const jumpButton = target.closest<HTMLElement>("[data-wizard-jump]");
233	    if (jumpButton) {
234	      event.preventDefault();
235	      const nextIndex = Number(jumpButton.dataset.wizardJump);
236	      if (Number.isNaN(nextIndex) || nextIndex > this._resolveFurthestAccessibleStep()) return;
237	      this._jump(nextIndex);
238	      return;
239	    }
240	
241	    if (target.closest("[data-wizard-next]")) {
242	      event.preventDefault();
243	      this._next();
244	      return;
245	    }
246	
247	    if (target.closest("[data-wizard-prev]")) {
248	      event.preventDefault();
249	      this._prev();
250	    }
251	  }
252	
253	  private _onSubmit(event: Event): void {
254	    if (this._submitting) {
255	      event.preventDefault();
256	      event.stopPropagation();
257	      return;
258	    }
259	    if (!this._isSubmitAllowed()) {
260	      event.preventDefault();
261	      event.stopPropagation();
262	      return;
263	    }
264	
265	    const currentStep = this._steps[this._current];
266	    if (!currentStep) return;
267	    if (!this._triggerValidationAndCheck(currentStep)) {
268	      event.preventDefault();
269	      event.stopPropagation();
270	      return;
271	    }
272	
273	    event.preventDefault();
274	    event.stopPropagation();
275	    void this._submit();
276	  }
277	
278	  private _onFormKeydown(event: KeyboardEvent): void {
279	    if (this._submitting) {
280	      event.preventDefault();
281	      return;
282	    }
283	    if (event.key !== "Enter") return;
284	    if (this._isSubmitAllowed()) return;
285	
286	    const target = event.target;
287	    if (target instanceof HTMLTextAreaElement) return;
288	    if (target instanceof HTMLButtonElement) return;
289	
290	    event.preventDefault();
291	  }
292	
293	  private _next(): void {
294	    if (this._busy || this._submitting || this._current >= this._steps.length - 1) return;
295	    const currentStep = this._steps[this._current];
296	    if (!currentStep) return;
297	    if (!this._triggerValidationAndCheck(currentStep)) return;
298	    this._go(this._current + 1, "next");
299	  }
300	
301	  private _prev(): void {
302	    if (this._busy || this._submitting || this._current <= 0) return;
303	    this._go(this._current - 1, "prev");
304	  }
305	
306	  private _jump(nextIndex: number): void {
307	    if (this._busy || this._submitting) return;
308	    if (nextIndex < 0 || nextIndex >= this._steps.length) return;
309	    if (nextIndex === this._current) return;
310	    this._go(nextIndex, nextIndex > this._current ? "next" : "prev");
311	  }
312	
313	  private _go(nextIndex: number, direction: string): void {
314	    const currentStep = this._steps[this._current];
315	    const nextStep = this._steps[nextIndex];
316	    if (!currentStep || !nextStep) return;
317	
318	    this._busy = true;
319	
320	    requestAnimationFrame(() => {
321	      currentStep.classList.remove("is-active");
322	      currentStep.classList.toggle("is-prev", direction === "next");
323	
324	      requestAnimationFrame(() => {
325	        nextStep.classList.remove("is-prev");
326	        nextStep.classList.add("is-active");
327	        nextStep.scrollTop = 0;
328	
329	        this._current = nextIndex;
330	        this._syncIndicator();
331	        this._syncSidebar();
332	
333	        this._trackedTimeout(() => {
334	          currentStep.classList.remove("is-prev");
335	          this._busy = false;
336	        }, CONTACT_WIZARD.transitionMs + CONTACT_WIZARD.transitionBufferMs);
337	      });
338	    });
339	  }
340	
341	  private _syncIndicator(immediate = false): void {
342	    const currentElement =
343	      this._root.querySelector<HTMLElement>("[data-wizard-current]");
344	    const barElement = this._root.querySelector<HTMLElement>("[data-wizard-bar]");
345	
346	    if (currentElement) {
347	      currentElement.textContent = String(this._current + 1).padStart(2, "0");
348	    }
349	
350	    if (barElement) {
351	      const scale = (this._current + 1) / this._steps.length;
352	      barElement.style.transform = `scaleX(${scale})`;
353	    }
354	
355	    this._syncActionState(immediate);
356	    this._syncSubmitAvailability();
357	  }
358	
359	  private _syncActionState(immediate = false): void {
360	    const isFirstStep = this._current === 0;
361	    const isLastStep = this._current === this._steps.length - 1;
362	
363	    this._prevButtons.forEach((button) => {
364	      this._syncPreviousAction(button, isFirstStep, immediate);
365	    });
366	
367	    this._primaryActionButtons.forEach((button) => {
368	      this._syncPrimaryAction(button, isLastStep);
369	    });
370	  }
