372	  private _syncPreviousAction(
373	    button: HTMLButtonElement,
374	    isFirstStep: boolean,
375	    immediate = false,
376	  ): void {
377	    const target = this._resolvePreviousActionTarget(button);
378	    this._clearPreviousActionHideTimer(target);
379	
380	    if (isFirstStep) {
381	      button.disabled = true;
382	      button.setAttribute("aria-disabled", "true");
383	      target.setAttribute("aria-hidden", "true");
384	      target.toggleAttribute("inert", true);
385	
386	      if (
387	        immediate ||
388	        target.hidden ||
389	        target.classList.contains(INIT_DOM_CLASSES.boxHidden)
390	      ) {
391	        this._hidePreviousActionImmediately(target);
392	        return;
393	      }
394	
395	      this._hidePreviousActionWithTransition(target);
396	      return;
397	    }
398	
399	    this._showPreviousActionTarget(target, immediate);
400	    button.disabled = this._submitting;
401	    button.setAttribute(
402	      "aria-disabled",
403	      this._submitting ? "true" : "false",
404	    );
405	  }
