407	  private _syncPrimaryAction(
408	    button: HTMLButtonElement,
409	    isSubmitMode: boolean,
410	  ): void {
411	    button.type = isSubmitMode ? "submit" : "button";
412	    button.disabled = this._submitting;
413	    button.classList.toggle("no-wizard-action--next", !isSubmitMode);
414	    button.classList.toggle("no-wizard-action--submit", isSubmitMode);
415	    button.setAttribute("aria-hidden", "false");
416	    button.setAttribute("aria-disabled", this._submitting ? "true" : "false");
417	
418	    if (isSubmitMode) {
419	      button.removeAttribute("data-wizard-next");
