422	    }
423	
424	    const text = button.querySelector<HTMLElement>(".no-corner-btn__text");
425	    if (text) {
426	      const nextLabel = isSubmitMode ? "Submit" : "Next";
427	      if (text.textContent !== nextLabel) {
428	        text.textContent = nextLabel;
429	      }
430	    }
431	  }
