438	  private _syncNavigationState(): void {
439	    const furthestAccessibleStep = this._resolveFurthestAccessibleStep();
440	
441	    this._navItems.forEach((item, index) => {
442	      const isCurrent = index === this._current;
443	      const isComplete = this._isStepSatisfied(this._steps[index]);
444	      const button = item.querySelector<HTMLButtonElement>(
445	        ".no-wizard-overview__button",
446	      );
447	
448	      item.classList.toggle("is-current", isCurrent);
449	      item.classList.toggle("is-complete", isComplete);
450	      item.classList.toggle("is-available", index <= furthestAccessibleStep);
451	
452	      if (!button) return;
453	      button.classList.toggle("is-framed", isCurrent);
454	      button.disabled = this._submitting || index > furthestAccessibleStep;
455	      button.setAttribute(
456	        "aria-label",
457	        `${this._resolveNavLabel(index)} ${this._resolveStepLabel(index)}`,
458	      );
459	      if (isCurrent) {
460	        button.setAttribute("aria-current", "step");
461	        return;
462	      }
463	      button.removeAttribute("aria-current");
464	    });
465	
466	    this._syncOverviewScroll();
467	  }
