469	  private _syncOverviewScroll(): void {
470	    if (!this._overviewList) return;
471	    if (this._lastOverviewScrollIndex === this._current) return;
472	
473	    const currentItem = this._navItems[this._current];
474	    if (!currentItem) return;
475	
476	    this._lastOverviewScrollIndex = this._current;
477	
478	    requestAnimationFrame(() => {
479	      const container = this._overviewList;
480	      if (!container) return;
481	
482	      const containerRect = container.getBoundingClientRect();
483	      const itemRect = currentItem.getBoundingClientRect();
484	      const padding = CONTACT_WIZARD.overviewScrollPadding;
485	      const offsetTop = itemRect.top - containerRect.top;
486	      const offsetBottom = itemRect.bottom - containerRect.bottom;
487	
488	      if (offsetTop < padding) {
489	        container.scrollTo({
490	          top: container.scrollTop + offsetTop - padding,
491	          behavior: "smooth",
492	        });
493	        return;
494	      }
495	
496	      if (offsetBottom > -padding) {
497	        container.scrollTo({
498	          top: container.scrollTop + offsetBottom + padding,
499	          behavior: "smooth",
500	        });
501	      }
502	    });
503	  }
