576	  private _syncChipList(
577	    node: HTMLElement,
578	    chipValues: ContactWizardChipData[],
579	  ): void {
580	    const previousPositions = this._captureChipPositions(node);
581	    const chipSet = new Set(chipValues.map((chip) => chip.key));
582	    const existingChips = new Map(
583	      Array.from(
584	        node.querySelectorAll<HTMLElement>(".no-wizard-overview__chip:not(.is-ghost)"),
585	      ).map((chip) => [chip.dataset.wizardChipKey ?? "", chip]),
586	    );
587	    let layoutChanged = false;
588	
589	    chipValues.forEach((value, index) => {
590	      const existingChip = existingChips.get(value.key);
591	      const chip = existingChip ?? this._createChip(value, index);
592	      this._cancelChipLeave(chip);
593	      this._syncChipContent(chip, value);
594	      chip.style.animationDelay = `${index * CONTACT_WIZARD.chipStaggerMs}ms`;
595	
596	      if (!existingChip) {
597	        node.append(chip);
598	        layoutChanged = true;
599	      }
600	    });
601	
602	    existingChips.forEach((chip, value) => {
603	      if (chipSet.has(value)) return;
604	      this._detachChipWithGhost(node, chip);
605	      layoutChanged = true;
606	    });
607	
608	    if (!layoutChanged) return;
609	    this._animateChipReflow(node, previousPositions);
610	  }
611	
612	  private _createChip(value: ContactWizardChipData, index: number): HTMLElement {
613	    const chip = document.createElement("span");
614	    chip.className = "no-wizard-overview__chip is-entering";
615	    chip.dataset.wizardChipKey = value.key;
616	    chip.dataset.wizardChipValue = value.label;
617	    this._syncChipContent(chip, value);
618	    chip.style.animationDelay = `${index * CONTACT_WIZARD.chipStaggerMs}ms`;
619	    chip.addEventListener(
620	      "animationend",
621	      () => {
622	        chip.classList.remove("is-entering");
623	      },
624	      { once: true },
625	    );
626	    return chip;
627	  }
628	
629	  private _syncChipContent(
630	    chip: HTMLElement,
631	    value: ContactWizardChipData,
632	  ): void {
633	    chip.dataset.wizardChipKey = value.key;
634	    chip.dataset.wizardChipValue = value.label;
635	    chip.classList.toggle(
636	      "no-wizard-overview__chip--with-icon",
637	      value.iconClass !== undefined,
638	    );
639	
640	    const currentLabel = chip.querySelector<HTMLElement>(
641	      ".no-wizard-overview__chip-label",
642	    );
643	    const currentIcon = chip.querySelector<HTMLElement>(
644	      ".no-wizard-overview__chip-icon",
645	    );
646	
647	    if (value.iconClass !== undefined) {
648	      const icon = currentIcon ?? document.createElement("i");
649	      icon.className = `no-wizard-overview__chip-icon ${value.iconClass}`;
650	      icon.setAttribute("aria-hidden", "true");
651	      this._syncAttachmentChipIcon(icon, value.iconClass);
652	      if (!icon.parentElement) {
653	        chip.prepend(icon);
654	      }
655	    } else {
656	      currentIcon?.remove();
657	    }
658	
659	    const label = currentLabel ?? document.createElement("span");
