675	
676	  private _resolveAttachmentIconClass(attachmentName: string): string {
677	    const extension = this._resolveAttachmentExtension(attachmentName);
678	    if (this._matchesAttachmentExtension(extension, CONTACT_WIZARD.attachmentImageExtensions)) {
679	      return CONTACT_WIZARD.attachmentIconClass.image;
680	    }
681	    if (this._matchesAttachmentExtension(extension, CONTACT_WIZARD.attachmentPdfExtensions)) {
682	      return CONTACT_WIZARD.attachmentIconClass.pdf;
683	    }
684	    if (this._matchesAttachmentExtension(extension, CONTACT_WIZARD.attachmentExcelExtensions)) {
685	      return CONTACT_WIZARD.attachmentIconClass.excel;
686	    }
687	    return CONTACT_WIZARD.attachmentIconClass.file;
688	  }
689	
690	  private _resolveAttachmentExtension(attachmentName: string): string {
691	    const segments = attachmentName.toLowerCase().split(".");
692	    return segments.length > 1 ? segments[segments.length - 1] ?? "" : "";
693	  }
694	
695	  private _matchesAttachmentExtension(
696	    extension: string,
697	    extensions: readonly string[],
698	  ): boolean {
699	    return extensions.some((candidate) => candidate === extension);
700	  }
701	
702	  private _syncAttachmentChipIcon(
703	    icon: HTMLElement,
704	    iconClass: string,
705	  ): void {
706	    icon.replaceChildren(this._createAttachmentIconSvg(iconClass));
707	  }
708	
709	  private _createAttachmentIconSvg(iconClass: string): SVGSVGElement {
710	    if (iconClass === CONTACT_WIZARD.attachmentIconClass.image) {
711	      return this._createImageIconSvg();
712	    }
713	    if (iconClass === CONTACT_WIZARD.attachmentIconClass.pdf) {
714	      return this._createPdfIconSvg();
715	    }
716	    if (iconClass === CONTACT_WIZARD.attachmentIconClass.excel) {
717	      return this._createExcelIconSvg();
718	    }
719	    return this._createFileIconSvg();
720	  }
