722	  private _detachChipWithGhost(node: HTMLElement, chip: HTMLElement): void {
723	    this._cancelChipLeave(chip);
724	
725	    const nodeRect = node.getBoundingClientRect();
726	    const chipRect = chip.getBoundingClientRect();
727	    const ghost = chip.cloneNode(true);
728	    if (!(ghost instanceof HTMLElement)) {
729	      chip.remove();
730	      return;
731	    }
732	
733	    ghost.classList.remove("is-entering");
734	    ghost.classList.add("is-leaving", "is-ghost");
735	    ghost.style.left = `${chipRect.left - nodeRect.left}px`;
736	    ghost.style.top = `${chipRect.top - nodeRect.top}px`;
737	    ghost.style.width = `${chipRect.width}px`;
738	    ghost.style.height = `${chipRect.height}px`;
739	
740	    node.append(ghost);
741	    chip.remove();
742	
743	    const timer = this._trackedTimeout(() => {
744	      this._chipLeaveTimers.delete(ghost);
745	      ghost.remove();
746	    }, CONTACT_WIZARD.chipLeaveMs);
747	
748	    this._chipLeaveTimers.set(ghost, timer);
749	  }
750	
751	  private _cancelChipLeave(chip: HTMLElement): void {
752	    const timer = this._chipLeaveTimers.get(chip);
753	    if (timer !== undefined) {
754	      window.clearTimeout(timer);
755	      this._chipLeaveTimers.delete(chip);
756	    }
757	    chip.classList.remove("is-leaving");
758	  }
759	
760	  private _captureChipPositions(node: HTMLElement): Map<HTMLElement, DOMRect> {
761	    return new Map(
762	      Array.from(
763	        node.querySelectorAll<HTMLElement>(".no-wizard-overview__chip:not(.is-ghost)"),
764	      ).map((chip) => [chip, chip.getBoundingClientRect()]),
765	    );
766	  }
767	
768	  private _animateChipReflow(
769	    node: HTMLElement,
770	    previousPositions: Map<HTMLElement, DOMRect>,
771	  ): void {
772	    requestAnimationFrame(() => {
773	      node
774	        .querySelectorAll<HTMLElement>(".no-wizard-overview__chip:not(.is-ghost)")
775	        .forEach((chip) => {
776	          if (chip.classList.contains("is-entering")) return;
777	
778	          const previousRect = previousPositions.get(chip);
779	          if (!previousRect) return;
780	
781	          const currentRect = chip.getBoundingClientRect();
782	          const deltaX = previousRect.left - currentRect.left;
783	          const deltaY = previousRect.top - currentRect.top;
784	
785	          if (Math.abs(deltaX) < 1 && Math.abs(deltaY) < 1) return;
786	
787	          this._chipMoveAnimations.get(chip)?.cancel();
788	          const animation = this._trackAnimation(
789	            chip.animate(
790	              [
791	                { transform: `translate(${deltaX}px, ${deltaY}px)` },
792	                { transform: "translate(0, 0)" },
793	              ],
794	              {
795	                duration: CONTACT_WIZARD.chipMoveMs,
796	                easing: CONTACT_WIZARD.chipMoveEase,
797	                fill: "both",
798	              },
799	            ),
800	          );
801	
802	          this._chipMoveAnimations.set(chip, animation);
803	          animation.addEventListener(
804	            "finish",
805	            () => {
806	              this._chipMoveAnimations.delete(chip);
807	            },
808	            { once: true },
809	          );
810	        });
811	    });
812	  }
813	
814	  private _resolveStepChipValues(stepIndex: number): string[] {
815	    if (stepIndex === 0) {
816	      return this._resolveProjectChipValues();
817	    }
818	
819	    if (stepIndex === 1) {
820	      return this._resolveSingleValueChip('input[name="budget"]:checked');
821	    }
822	
823	    if (stepIndex === 2) {
824	      return this._resolveSingleValueChip('input[name="period"]:checked');
825	    }
826	
827	    if (stepIndex === 3) {
828	      return this._resolveContactInfoChipValues();
829	    }
830	
831	    return [];
832	  }
833	
834	  private _resolveSingleValueChip(selector: string): string[] {
835	    const value = this._resolveChoiceLabel(selector);
836	    return value === "" ? [] : [value];
837	  }
838	
839	  private _resolveProjectChipValues(): string[] {
840	    return Array.from(
841	      this._root.querySelectorAll<HTMLInputElement>('input[name="project[]"]'),
842	    )
843	      .filter((input) => input.checked)
844	      .flatMap((input) => {
845	        const label = this._resolveLabelText(input);
846	        if (label === "") return [];
